import{_ as s,C as o,o as d,c as e,j as t,E as r,a as n,a2 as l}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"n":4,"bob":"II-bob · 2D grafika asoslari va Photoshop","lessons":[{"g":10,"title":"Ranglar nazariyasi va dizayn asoslari (3-qism): O'yin atmosferasiga mos rang palitrasi yaratish","lead":"Bir xil o'rmonni kunduzi quvnoq, tunda esa qo'rqinchli qilib ko'rsatish mumkin — faqat ranglarni almashtirib. Bugun o'yiningiz uchun o'z rang palitrangizni yaratamiz.","link":"/mentor/9-sinf-game/hafta-04/dars-1","slide":"/slaydlar/9-sinf-game/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-1-test.html"},{"g":11,"title":"O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","lead":"Yurak belgisini ko'rgan har bir o'yinchi «bu jon» deb biladi — bir so'z ham o'qimasdan. Bugun o'yinlarning «tili» bo'lgan ikonkalar va spraytlar bilan tanishamiz va birinchi ikonkamizni yaratamiz.","link":"/mentor/9-sinf-game/hafta-04/dars-2","slide":"/slaydlar/9-sinf-game/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-2-test.html"},{"g":12,"title":"O'yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish","lead":"Mario ham bir paytlar bir necha o'nlab pikseldan iborat edi! Bugun 32×32 piksel ichida o'z qahramoningizni yaratasiz, unga tanga va zelye chizasiz va uni «nafas oldirasiz».","link":"/mentor/9-sinf-game/hafta-04/dars-3","slide":"/slaydlar/9-sinf-game/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-04/index.md","filePath":"mentor/9-sinf-game/hafta-04/index.md"}`),h={name:"mentor/9-sinf-game/hafta-04/index.md"},u={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},y={class:"blk"},m={id:"baholash-mezoni",tabindex:"-1"};function k(c,a,b,p,f,v){const i=o("Icon");return d(),e("div",null,[t("div",u,[t("h2",g,[r(i,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Barcha fayllarni bitta <code>4-hafta_Ism</code> papkasida saqlang — ular 13-darsda (sprayt sheet) kerak bo&#39;ladi.</p><hr><h2 id="_10-dars-ranglar-nazariyasi-va-dizayn-asoslari-3-qism-o-yin-atmosferasiga-mos-rang-palitrasi" tabindex="-1">10-dars: Ranglar nazariyasi va dizayn asoslari (3-qism): O&#39;yin atmosferasiga mos rang palitrasi <a class="header-anchor" href="#_10-dars-ranglar-nazariyasi-va-dizayn-asoslari-3-qism-o-yin-atmosferasiga-mos-rang-palitrasi" aria-label="Permalink to &quot;10-dars: Ranglar nazariyasi va dizayn asoslari (3-qism): O&#39;yin atmosferasiga mos rang palitrasi&quot;">​</a></h2><ol><li>O&#39;z o&#39;yiningiz uchun bitta lokatsiya tanlang va uning kayfiyatini bitta jumlada yozing.</li><li>5–8 ta rasmdan iborat mood board tuzing (Photoshop xolsti).</li><li>6–8 rangli palitra yarating: asosiy rang, 1 ta aksent, har bir asosiy rang uchun soya va yorug&#39;lik pog&#39;onasi (hue shifting bilan).</li><li>Palitrani oddiy sinov sahnasida (fon + qahramon siluyeti) qo&#39;llab, <code>Black &amp; White</code> adjustment layer bilan kulrang testdan o&#39;tkazing.</li><li>Swatches panelida guruh qilib saqlang va <code>.aco</code> ga eksport qiling; HEX kodli palitra kartasini PNG qilib saqlang.</li></ol><p><strong>Kutiladigan natija:</strong> mood board, <code>.aco</code> fayli, palitra kartasi (PNG) va kulrang test skrinshoti.</p><hr><h2 id="_11-dars-o-yin-uchun-ikonka-va-spraytlar-yaratish-1-qism-sprayt-va-ikonka-tushunchasi-formatlar" tabindex="-1">11-dars: O&#39;yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar <a class="header-anchor" href="#_11-dars-o-yin-uchun-ikonka-va-spraytlar-yaratish-1-qism-sprayt-va-ikonka-tushunchasi-formatlar" aria-label="Permalink to &quot;11-dars: O&#39;yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar&quot;">​</a></h2><ol><li>Sevimli o&#39;yiningizdan 3 ta ikonka va 3 ta spraytni topib, har birining turini yozing.</li><li>Photoshop&#39;da (yoki Piskel&#39;da) bir uslubdagi 4 ta ikonka yarating: jon, tanga, kalit, sozlamalar — 10-dars palitrasidan foydalaning.</li><li>Har bir ikonkani shaffof fonli PNG qilib 128, 64 va 32 px o&#39;lchamlarda eksport qiling; fayllarni <code>ikon_nom_olcham.png</code> qoidasi bilan nomlang.</li><li>32 px da qaysi ikonka yomon tanilishini aniqlab, uni soddalashtiring va 2 jumlada nima o&#39;zgartirganingizni yozing.</li></ol><p><strong>Kutiladigan natija:</strong> 12 ta PNG fayl va qisqa tahlil.</p><hr><h2 id="_12-dars-o-yin-uchun-ikonka-va-spraytlar-yaratish-2-qism-personaj-va-obyektlar-uchun-spraytlar" tabindex="-1">12-dars: O&#39;yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar <a class="header-anchor" href="#_12-dars-o-yin-uchun-ikonka-va-spraytlar-yaratish-2-qism-personaj-va-obyektlar-uchun-spraytlar" aria-label="Permalink to &quot;12-dars: O&#39;yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar&quot;">​</a></h2><ol><li>32×32 px da o&#39;z qahramoningizning to&#39;liq spraytini chizing: siluyet → flat → soya → yorug&#39;lik → 1 px kontur (5 ta nomlangan qatlam).</li><li>16×16 px da 2 ta obyekt chizing (tanga, zelye, kalit yoki sandiq) — qahramon bilan bir uslubda.</li><li>Qahramon uchun 2 kadrli idle animatsiya yarating (Timeline, 0.5 s, Forever).</li><li>Eksport: qahramon va obyektlar — shaffof PNG (100% va 800%, Nearest Neighbor), animatsiya — GIF.</li></ol><p><strong>Kutiladigan natija:</strong> <code>.psd</code> fayl, 3 ta PNG sprayt, <code>qahramon_idle.gif</code>.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>10-dars vazifasi (30 ball):</strong> palitrada asosiy/aksent rang va value pog&#39;onalari borligi, hue shifting to&#39;g&#39;ri qo&#39;llangani, kulrang test o&#39;tkazilgani, <code>.aco</code> va palitra kartasi saqlangani.</li><li><strong>11-dars vazifasi (35 ball):</strong> ikonkalar bir uslubda (kontur, yorug&#39;lik, palitra), shaffof PNG, 3 o&#39;lchamda eksport va 32 px da tanilishi.</li><li><strong>12-dars vazifasi (35 ball):</strong> siluyet aniqligi, cheklangan palitra, yorug&#39;lik yo&#39;nalishi, kontur tozaligi, Nearest Neighbor bilan kattalashtirish va ishlaydigan idle animatsiya.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar <code>.psd</code> fayllarini ham topshirsin — qatlamlar nomlanishi va tartibini tekshirish uchun.</li></ul>',19))]),t("div",y,[t("h2",m,[r(i,{name:"list-checks"}),a[3]||(a[3]=n(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p><strong>Mavzular:</strong></p><ol><li>Ranglar nazariyasi va dizayn asoslari (3-qism): O&#39;yin atmosferasiga mos rang palitrasi yaratish</li><li>O&#39;yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)</li><li>O&#39;yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Atmosfera palitrasi</strong></td><td>Kayfiyat jumlasi va mood board, asosiy va aksent rang, value pog&#39;onalari va hue shifting, kulrang test, Swatches guruhi va <code>.aco</code> eksport</td><td>30 ball</td></tr><tr><td><strong>Ikonkalar va formatlar</strong></td><td>Ikonka turlari, ikonka va sprayt farqi, PNG/SVG/GIF tanlovi, shaffof fonli ikonka (Custom Shape, Clipping Mask), kichik o&#39;lchamda tanilishi, litsenziya</td><td>35 ball</td></tr><tr><td><strong>Sprayt chizish</strong></td><td>Siluyet, cheklangan palitra, yuqori chapdan yorug&#39;lik, 1 px kontur, piksel-art tozaligi (orphan, doubles), Nearest Neighbor, 2 kadrli idle animatsiya</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Palitra (30)</th><th>Ikonkalar (35)</th><th>Spraytlar (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar soyani qora bilan bo&#39;yashga moyil — hue shifting jadvalini ekranda qoldiring. Ikonkalarni oq fon bilan eksport qilish (Transparent hujjat ochilmagan yoki JPG tanlangan) eng ko&#39;p uchraydigan texnik xato. Piksel-artda Brush Tool va Bicubic interpolyatsiya spraytni loyqa qiladi — dars boshida Pencil va Nearest Neighbor sozlamalarini hammada tekshiring.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> 4 kadrli yurish (walk) siklini chizish; Aseprite yoki Piskel&#39;da onion skin bilan ishlash; bitta qahramon uchun kunduzgi va tungi palitra variantlarini (palette swap) tayyorlash.</li><li><strong>Keyingi haftaga ko&#39;prik:</strong> 13-darsda (3-qism) bu haftada chizilgan kadrlar va obyektlar <strong>sprayt sheet (atlas)</strong> ga yig&#39;iladi va optimallashtiriladi — o&#39;quvchilar barcha PNG fayllarini bitta papkada saqlab kelsin.</li></ul>',12))])])}const _=s(h,[["render",k]]);export{z as __pageData,_ as default};
